     1	import {createChatOrchestrator} from './chatOrchestrator.js';
     2	import type {OrchestratorHooks} from './chatOrchestrator.js';
     3	import {ToolRegistry} from './tools/registry.js';
     4	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
     5	import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
     6	import type {ChatSession} from '../types/session.js';
     7	
     8	const promptBuilder = new PromptBuilder({identity: 'Usage acceptance test.'});
     9	const session = (): ChatSession => ({
    10	  sessionId: 'usage-session',
    11	  userId: 'usage-user',
    12	  entries: [{role: 'user', content: 'Use the tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
    13	});
    14	
    15	const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};
    16	const TOOL_STOP: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
    17	const DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
    18	
    19	const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
    20	  let round = 0;
    21	
    22	  return {
    23	    async *sendMessage(): AsyncGenerator<MessageChunk> {
    24	      yield* rounds[round++] ?? [];
    25	    },
    26	    async generateStructured<T>(): Promise<T> {
    27	      return {} as T;
    28	    },
    29	  };
    30	};
    31	
    32	const lookupRegistry = (): ToolRegistry => {
    33	  const registry = new ToolRegistry();
    34	  registry.register(
    35	    {name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}},
    36	    async () => 'found'
    37	  );
    38	  return registry;
    39	};
    40	
    41	const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});
    42	
    43	describe('afterModelResponse usage across tool rounds', () => {
    44	  it('reports the summed usage from every provider call in a turn with two tool rounds', async () => {
    45	    let reported: UsageMetadata | undefined;
    46	    const hooks: OrchestratorHooks = {
    47	      afterModelResponse: async (_session, _text, usage) => {
    48	        reported = usage;
    49	      },
    50	    };
    51	    const orchestrator = createChatOrchestrator(
    52	      scriptedProvider([
    53	        [TOOL_CALL, usageStop('tool_use', {inputTokens: 11, outputTokens: 2, totalTokens: 13})],
    54	        [TOOL_CALL, usageStop('tool_use', {inputTokens: 23, outputTokens: 3, totalTokens: 26})],
    55	        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 37, outputTokens: 5, totalTokens: 42})],
    56	      ]),
    57	      promptBuilder,
    58	      lookupRegistry(),
    59	      {hooks}
    60	    );
    61	
    62	    await orchestrator.processMessage(session());
    63	
    64	    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
    65	  });
    66	
    67	  it('counts reported rounds while leaving a turn with no reported usage undefined', async () => {
    68	    const reports: Array<UsageMetadata | undefined> = [];
    69	    const hooks: OrchestratorHooks = {
    70	      afterModelResponse: async (_session, _text, usage) => {
    71	        reports.push(usage);
    72	      },
    73	    };
    74	    const withGaps = createChatOrchestrator(
    75	      scriptedProvider([
    76	        [TOOL_CALL, usageStop('tool_use', {inputTokens: 2, outputTokens: 1, totalTokens: 3})],
    77	        [TOOL_CALL, TOOL_STOP],
    78	        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 7, outputTokens: 4, totalTokens: 11})],
    79	      ]),
    80	      promptBuilder,
    81	      lookupRegistry(),
    82	      {hooks}
    83	    );
    84	    const withoutUsage = createChatOrchestrator(
    85	      scriptedProvider([[{type: 'text', text: 'Done.'}, DONE]]),
    86	      promptBuilder,
    87	      undefined,
    88	      {hooks}
    89	    );
    90	
    91	    await withGaps.processMessage(session());
    92	    await withoutUsage.processMessage(session());
    93	
    94	    expect(reports).toEqual([{inputTokens: 9, outputTokens: 5, totalTokens: 14}, undefined]);
    95	  });
    96	});
}

export function collectToolCalls(chunk: MessageChunk, pendingToolCalls: ToolCall[]): void {
  if (chunk.type === 'tool_use') pendingToolCalls.push(chunk.toolCall);
}

export function extractStopReason(chunk: MessageChunk): string | null {
  return chunk.type === 'stop' ? chunk.stopReason : null;
}

export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}
